@use './styles/tokens';
// Include theming for Angular Material with `mat.theme()`.
// This Sass mixin will define CSS variables that are used for styling Angular Material
// components according to the Material 3 design spec.
// Learn more about theming and how to use it for your application's
// custom components at https://material.angular.dev/guide/theming
@use '@angular/material' as mat;

/* Map Angular Material system variables to our design tokens (CSS custom properties).
   This makes Material components use our token colors and typography at runtime. */
:root {
  --mat-sys-primary: var(--color-primary);
  --mat-sys-on-primary: var(--color-primary-contrast);
  --mat-sys-secondary: var(--color-accent);
  --mat-sys-on-secondary: var(--color-primary-contrast);

  --mat-sys-surface: var(--color-surface);
  --mat-sys-on-surface: var(--text-high);
  --mat-sys-background: var(--color-background);
  --mat-sys-on-background: var(--text-high);

  --mat-sys-body-medium: var(--font-size-base)/var(--line-height-base) var(--font-family-base);
}

html {
  height: 100%;
  @include mat.theme(
    (
      // keep typography enabled and density set to 0
      typography: Roboto,
      density: 0,
    )
  );
}

body {
  // Default the application to a light color theme. This can be changed to
  // `dark` to enable the dark color theme, or to `light dark` to defer to the
  // user's system settings.
  color-scheme: light;

  // Use Material system-level CSS variables that we map above to our tokens
  background-color: var(--mat-sys-surface);
  color: var(--mat-sys-on-surface);
  font: var(--mat-sys-body-medium);

  // Reset the user agent margin.
  margin: 0;
  height: 100%;
}

/* Global base styles */
html,
body {
  height: 100%;
  margin: 0;
  padding: 0;
  font-family: var(--font-family-base);
  font-size: var(--font-size-base);
  line-height: var(--line-height-base);
  color: var(--text-high);
  background-color: var(--color-background);
}

a {
  color: var(--color-primary);
  text-decoration: none;
}

button {
  font-family: inherit;
}

import { ApplicationConfig, provideBrowserGlobalErrorListeners } from '@angular/core';
import { provideRouter } from '@angular/router';
import { provideAnimationsAsync } from '@angular/platform-browser/animations';

import { routes } from './app.routes';

export const appConfig: ApplicationConfig = {
  providers: [
    provideBrowserGlobalErrorListeners(),
    provideRouter(routes),
    provideAnimationsAsync()
  ]
};

