import { Component, Inject } from '@angular/core';
import { CommonModule } from '@angular/common';
import { MatDialogModule, MatDialogRef, MAT_DIALOG_DATA } from '@angular/material/dialog';
import { MatButtonModule } from '@angular/material/button';

export interface ConfirmDialogData {
  title: string;
  message: string;
  confirmText?: string;
  cancelText?: string;
}

@Component({
  selector: 'app-confirm-dialog',
  standalone: true,
  imports: [CommonModule, MatDialogModule, MatButtonModule],
  templateUrl: './confirm-dialog.html',
  styleUrls: ['./confirm-dialog.scss'],
})
export class ConfirmDialog {
  constructor(
    public dialogRef: MatDialogRef<ConfirmDialog>,
    @Inject(MAT_DIALOG_DATA) public data: ConfirmDialogData
  ) {}
}

/* Minimal styling for confirm dialog using design tokens */
:host {
  display: block;
}

mat-dialog-content p {
  margin: 0;
  color: var(--text-high);
}

mat-dialog-actions button {
  margin-left: var(--space-xs);
}

import { Component } from '@angular/core';
import { CommonModule } from '@angular/common';
import { RouterModule, Router } from '@angular/router';
import { MatCardModule } from '@angular/material/card';
import { MatChipsModule } from '@angular/material/chips';
import { MatButtonModule } from '@angular/material/button';
import { MatDialogModule, MatDialog } from '@angular/material/dialog';
import { ConfirmDialog } from '../../shared/confirm-dialog/confirm-dialog';
import { RECIPES, CATEGORIES, Recipe } from '../../in-memory';

@Component({
  selector: 'app-recipe-list',
  standalone: true,
  imports: [CommonModule, RouterModule, MatCardModule, MatChipsModule, MatButtonModule, MatDialogModule, ConfirmDialog],
  templateUrl: './recipe-list.html',
  styleUrls: ['./recipe-list.scss'],
})
export class RecipeList {
  recipes: Recipe[] = RECIPES;

  // category id -> category map for quick lookup
  categoryMap = new Map(CATEGORIES.map((c) => [c.id, c]));

  constructor(private router: Router, private dialog: MatDialog) {}

  trackById(_: number, item: Recipe) {
    return item.id;
  }

  logout() {
    const ref = this.dialog.open(ConfirmDialog, {
      data: {
        title: 'Kijelentkezés',
        message: 'Biztosan ki szeretnél jelentkezni?',
      },
    });

    ref.afterClosed().subscribe((result) => {
      if (result) {
        this.router.navigate(['/auth/login']);
      }
    });
  }
}

import { Component } from '@angular/core';
import { CommonModule } from '@angular/common';
import { ReactiveFormsModule, FormBuilder, Validators, FormGroup } from '@angular/forms';
import { Router } from '@angular/router';
import { MatFormFieldModule } from '@angular/material/form-field';
import { MatInputModule } from '@angular/material/input';
import { MatIconModule } from '@angular/material/icon';
import { MatButtonModule } from '@angular/material/button';
import { MatSnackBarModule, MatSnackBar } from '@angular/material/snack-bar';

@Component({
  selector: 'app-login',
  standalone: true,
  imports: [CommonModule, ReactiveFormsModule, MatFormFieldModule, MatInputModule, MatIconModule, MatButtonModule, MatSnackBarModule],
  templateUrl: './login.html',
  styleUrls: ['./login.scss'],
})
export class Login {
  form!: FormGroup;
  hide = true;

  constructor(private fb: FormBuilder, private router: Router, private snackBar: MatSnackBar) {
    this.form = this.fb.group({
      email: ['', [Validators.required, Validators.email]],
      password: ['', [Validators.required]],
    });
  }

  togglePasswordVisibility() {
    this.hide = !this.hide;
  }

  get email() {
    return this.form.get('email');
  }

  get password() {
    return this.form.get('password');
  }

  login() {
    if (this.form.valid) {
      // TODO: call AuthService to authenticate; for now navigate to recipes
      this.snackBar.open('Sikeres bejelentkezés!', undefined, { duration: 3000 });
      this.router.navigate(['/recipes']);
    } else {
      this.form.markAllAsTouched();
      this.snackBar.open('Kérjük, töltsd ki az összes mezőt!', undefined, { duration: 3000, panelClass: ['snackbar-warn'] });
    }
  }

  goToRegister() {
    this.router.navigate(['/auth/register']);
  }
}

